#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the path matrix.
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       path[i][j] = i*j%7+1;
 *       if ((i+j)%13 == 0 || (i+j)%7==0 || (i+j)%11 == 0)
 *          path[i][j] = 999;
 *     }
 *
 * C array path[i][j] is mapped to Buffer(j, i).
 */
static void init_array(int n, Buffer<num_t, 2> path) {
    // i = row (slow), j = column (fast)
    Var i("i"), j("j");
    Func init_path("init_path");

    // Base value: i * j % 7 + 1
    Expr base = cast<num_t>((i * j % 7) + 1);

    // Condition for setting to 999
    Expr sum = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    // Buffer layout is (x = j, y = i).
    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             base);

    // -------------------------
    // Schedule for initialization
    // -------------------------
    // Use a target that respects HL_JIT_TARGET / HL_TARGET.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var j_outer("j_outer"), j_inner("j_inner");

    // Row-major traversal: i (row) outer, j (col) inner.
    // Parallelize across rows, vectorize across columns.
    init_path
        .split(j, j_outer, j_inner, vec_width)
        .parallel(i)
        .vectorize(j_inner);

    init_path.compile_jit(target);
    init_path.realize(path);
}

/**
 * Print the path matrix (mainly to prevent dead-code elimination
 * and for optional correctness checking).
 *
 * Mirrors the PolyBench print_array semantics, but prints to stderr.
 */
static void print_array(int n, Buffer<num_t, 2> path) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // path[i][j] -> path(j, i)
            std::cerr << path(j, i) << '\n';
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to: DATA_TYPE path[N][N]
    // We use two buffers for double-buffered Floyd–Warshall.
    Buffer<num_t, 2> path0(n, n);
    Buffer<num_t, 2> path1(n, n);

    // Initialize data into path0
    init_array(n, path0);

    // Halide parameters and pipeline for a single Floyd–Warshall step.
    //
    // We follow the recommended DP translation pattern:
    //   For each k:
    //     step(i,j) = min(path(i,j), path(i,k) + path(k,j))
    //   implemented as a Func that reads from an ImageParam (current path)
    //   and a scalar Param k, and then executed from a host-side loop
    //   with double-buffering.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func floyd_step("floyd_step");

    // Mapping:
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k, i)
    //   C: path[k][j] -> path_param(j, k)
    Expr current = path_param(j, i);
    Expr via_k   = path_param(k_param, i) + path_param(j, k_param);

    floyd_step(j, i) = Halide::min(current, via_k);

    // -------------------------
    // Schedule for the FW step
    // -------------------------
    // Use the same notion of row-major traversal:
    //   outer loops over i (rows), inner over j (cols).
    // Tile and vectorize to improve locality and use SIMD.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes; chosen to give good cache behavior on
    // typical x86-64 CPUs. Adjust if needed for other hardware.
    const int TILE_I = 32;               // rows per tile
    const int TILE_J = vec_width * 8;    // columns per tile (multiple of SIMD width)

    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    // Layout after tiling:
    //  for (io over rows in tiles)  [parallel]
    //    for (jo over cols in tiles)
    //      for (ii within tile rows)
    //        for (ji within tile cols) [vectorized]
    floyd_step
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        .vectorize(ji, vec_width)
        .parallel(io);

    // Bind initial data and compile the step once.
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop
    floyd_step.compile_jit(target);

